  ('e1000000-0000-4000-a000-0000000008d1', 'EM-HIS-00001', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Chegada da esquadra de Cabral", ocorrido em 1500, pertence a qual período da história do Brasil?', 'Chegada da esquadra de Cabral (1500, Período Pré-Colonial): início da presença portuguesa e da exploração do pau-brasil.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000008d2', 'EM-HIS-00002', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Criação das capitanias hereditárias", ocorrido em 1534, pertence a qual período da história do Brasil?', 'Criação das capitanias hereditárias (1534, Brasil Colônia): divisão do território em faixas entregues a donatários.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000008d3', 'EM-HIS-00003', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Instalação do Governo-Geral", ocorrido em 1549, pertence a qual período da história do Brasil?', 'Instalação do Governo-Geral (1549, Brasil Colônia): centralização da administração colonial em Salvador.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000008d4', 'EM-HIS-00004', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Invasões holandesas no Nordeste", ocorrido em 1630, pertence a qual período da história do Brasil?', 'Invasões holandesas no Nordeste (1630, Brasil Colônia): ocupação de Pernambuco ligada ao comércio do açúcar.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000008d5', 'EM-HIS-00005', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Inconfidência Mineira", ocorrido em 1789, pertence a qual período da história do Brasil?', 'Inconfidência Mineira (1789, Brasil Colônia): conspiração contra a cobrança de impostos (derrama) sobre o ouro.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000008d6', 'EM-HIS-00006', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Conjuração Baiana", ocorrido em 1798, pertence a qual período da história do Brasil?', 'Conjuração Baiana (1798, Brasil Colônia): revolta popular com participação de pessoas escravizadas e ideias de igualdade.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000008d7', 'EM-HIS-00007', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Chegada da família real portuguesa", ocorrido em 1808, pertence a qual período da história do Brasil?', 'Chegada da família real portuguesa (1808, Período Joanino): abertura dos portos às nações amigas.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000008d8', 'EM-HIS-00008', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Independência do Brasil", ocorrido em 1822, pertence a qual período da história do Brasil?', 'Independência do Brasil (1822, Primeiro Reinado): separação política de Portugal, liderada por D. Pedro I.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000008d9', 'EM-HIS-00009', 8, 149, 'enem', 2, 1, 2026, 'multiple_choice', 'Linha do tempo do Brasil', 'O evento "Primeira Constituição do Brasil", ocorrido em 1824, pertence a qual período da história do Brasil?', 'Primeira Constituição do Brasil (1824, Primeiro Reinado): criação do Poder Moderador, exclusivo do imperador.', 'Situe o evento na linha do tempo: Colônia, Império (1822–1889) ou República (desde 1889).', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
